mapper.select:
SELECT warehouse_id, tenant_id, code, name, country_code, created_at
FROM wms_warehouse
WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}

mapper.update:
UPDATE wms_inventory_balance
SET on_hand = #{onHand}, reserved = #{reserved}, in_transit = #{inTransit}, frozen = #{frozen}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId} AND seller_sku = #{sellerSku}

mapper.select:
SELECT location_id, tenant_id, warehouse_id, zone_code, aisle, rack, shelf, bin, barcode, enabled, created_at, updated_at
FROM wms_warehouse_location
WHERE tenant_id = #{tenantId} AND location_id = #{locationId}

mapper.update:
UPDATE wms_stock_check
SET status = #{status},
    scheduled_at = #{scheduledAt},
    completed_at = #{completedAt},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND check_id = #{checkId}

mapper.select:
SELECT check_id, tenant_id, warehouse_id, check_type, status, scheduled_at, completed_at, created_at, updated_at
FROM wms_stock_check
WHERE tenant_id = #{tenantId} AND check_id = #{checkId}

SELECT transaction_id, tenant_id, warehouse_id, seller_sku, transaction_type, quantity,
       before_on_hand, before_reserved, after_on_hand, after_reserved,
       reference_type, reference_id, remark, created_at, batch_no, operator_id,
       pending_inspection_delta, pending_putaway_delta, quarantined_delta
FROM wms_inventory_transaction
WHERE tenant_id = #{tenantId}

    AND warehouse_id = #{warehouseId}


    AND seller_sku = #{sellerSku}

ORDER BY created_at DESC, transaction_id DESC
